  const maxHum    = parseFloat(cols[6]);
  const csvPress  = parseFloat(cols[7]); // reference max pressure for this med

  const reasons = [];

  // Temperature check
  if (temp < minTemp) reasons.push(`T=${temp}°C below min ${minTemp}°C`);
  if (temp > maxTemp) reasons.push(`T=${temp}°C above max ${maxTemp}°C`);

  // Humidity check
  if (hum < minHum) reasons.push(`H=${hum}% below min ${minHum}%`);
  if (hum > maxHum) reasons.push(`H=${hum}% above max ${maxHum}%`);

  // Pressure check — ONLY alert if sensor pressure EXCEEDS CSV value
  if (press > csvPress) reasons.push(`P=${press}hPa exceeds max ${csvPress}hPa`);

  if (reasons.length > 0) {
    issues.push(`• ${id} ${name}: ${reasons.join(', ')}`);
  }
}

